static int add_force_a_subtype_not_in_play(int player, event_t event, subtype_t subtype, int mode)
{
  if (event != EVENT_CHANGE_TYPE)
    return 0;
  if (!(land_can_be_played & 0x20000))
  {
    land_can_be_played |= 0x10000;
    return 0;
  }
  for (int slot = 0; slot < 15; ++slot)
    if (added_subtypes_not_in_play[player][slot].subtype == SUBTYPE_INVALID)
    {
      added_subtypes_not_in_play[player][slot].subtype = subtype;
      added_subtypes_not_in_play[player][slot].added_forced = (unsigned char)mode;
      return 1;
    }
  return 0;
}

static int can_cast_caf(int player, int card)
{
  int count = count_graveyard(player);
  const int *grave = get_grave(player);
  for (int pos = count; pos >= 0; --pos)
    if (is_what(-1, grave[pos], TYPE_SPELL) && get_cmc_by_internal_id(grave[pos]) <= 3 &&
        has_mana_to_cast_id(player, EVENT_CAN_CAST, cards_data[grave[pos]].id))
      return 1;
  return 0;
}

static void create_encore_granted_legacy(int player, int card, int graveyard_pos)
{
  if (graveyard_pos < 0)
    backtrace_and_abort("cards/commander_legends.c:539\ngraveyard_pos >= 0");
  int legacy = create_legacy_activate(player, card, encore_granted_legacy);
  card_instance_t *instance = get_card_instance(player, legacy);
  const int *grave = get_grave(player);
  instance->targets[0].card = grave[graveyard_pos];
  instance->targets[1].player = graveyard_source[player][graveyard_pos];
  instance->targets[1].card = graveyard_pos;
  instance->targets[2].card = player;
  instance->targets[3].player = player;
  instance->targets[3].card = card;
  create_card_name_legacy(player, legacy, cards_data[grave[graveyard_pos]].id);
}

static int create_livio_legacy(int player, int card, int t_player, int t_card)
{
  int iid = get_original_internal_card_id(t_player, t_card);
  int owner = get_owner(t_player, t_card);
  int legacy = owner == player ? create_legacy_effect(player, card, card_exiled_with_aegis_counter)
      : create_legacy_effect_for_opponent(player, card, card_exiled_with_aegis_counter, -1, -1);
  if (legacy != -1)
  {
    add_counters(player, card, owner, legacy, COUNTER_AEGIS, 1);
    card_instance_t *instance = get_card_instance(owner, legacy);
    unsigned int csvid = (uint16_t)cards_data[iid].id;
    instance->targets[0].card = iid;
    instance->display_pic_csv_id = csvid;
    instance->targets[0].player = owner;
    instance->eot_toughness = 0x300;
    instance->display_pic_num = (uint16_t)get_card_image_number(csvid, t_player, t_card);
  }
  kill_card(t_player, t_card, KILL_EXILE);
  return legacy;
}

static void create_spell_has_flashback_legacy_for_hl(int player, int card, int graveyard_pos,
                                                    flashback_legacy_t mode)
{
  if (graveyard_pos < 0)
    return;
  int legacy = create_legacy_activate(player, card, spell_has_flashback_legacy_for_hl);
  card_instance_t *instance = get_card_instance(player, legacy);
  int graveyard_player = get_card_instance(player, card)->targets[0].player;
  const int *grave = get_grave(graveyard_player);
  instance->targets[0].card = grave[graveyard_pos];
  instance->targets[1].player = graveyard_source[graveyard_player][graveyard_pos];
  instance->targets[1].card = graveyard_pos;
  instance->targets[2].player = mode;
  instance->targets[2].card = graveyard_player;
  instance->targets[3].player = player;
  instance->targets[3].card = card;
  create_card_name_legacy(player, legacy, cards_data[grave[graveyard_pos]].id);
}

static inst_info_t info_outofline(card_instance_t *inst, int cid)
{
  inst_info_t *entries = inst->ext->inst_info_data;
  int slot;
  for (slot = 0; slot < 6; ++slot)
  {
    if ((uint32_t)entries[slot].id == (uint32_t)cid)
      return entries[slot];
    if (entries[slot].id == 0)
      break;
  }
  if (slot == 6)
    slot = 5;
  entries[slot].id = (uint16_t)cid;
  entries[slot].data2 = 0;
  entries[slot].data = 0;
  return entries[slot];
}

static void modify_casting_cost_for_colorless_only_mana(int player, int card, event_t event,
                                                        int generic, int number_of_colorless_only_mana)
{
  if (event == EVENT_MODIFY_COST)
  {
    int cost = get_updated_casting_cost(player, card, -1, EVENT_CAST_SPELL,
                                       generic + number_of_colorless_only_mana);
    if (player_has_generic_and_colorless_available(player, cost - number_of_colorless_only_mana,
                                                   number_of_colorless_only_mana))
      null_casting_cost(player, card);
    else
      infinite_casting_cost();
  }
}

static int pay_aftermath(int player, int card, int iid, event_t event, int colorless,
                         int black, int blue, int green, int red, int white)
{
  int cost = get_updated_casting_cost(player, -1, iid, event, colorless);
  if (colorless == -1 && cost == 0)
    charge_mana_multi(player, -1, black, blue, green, red, white);
  else
  {
    charge_mana_multi(player, cost, black, blue, green, red, white);
    if (colorless == -1 && cost != 0)
      charge_mana(player, COLOR_COLORLESS, -1);
  }
  card_instance_t *instance = get_card_instance(player, card);
  int success = spell_fizzled != 1;
  instance->targets[1].card = x_value;
  return success;
}

static int play_card_in_exile_for_free_and_exile_it(int player, int t_player, int csvid)
{
  int iid = get_internal_card_id_from_csv_id(csvid);
  if (!can_legally_play_iid(player, iid))
    return 0;
  remove_card_from_rfg(t_player, csvid);
  int card = add_card_to_hand(player, iid);
  set_special_flags(player, card, SF_EXILE_ON_RESOLUTION);
  if (player != t_player)
  {
    if (player == 0 && t_player == 1)
      add_state(player, card, STATE_OWNED_BY_OPPONENT);
    else
      remove_state(player, card, STATE_OWNED_BY_OPPONENT);
  }
  int result = real_play_spell_for_free(player, card, (int)0x80000000U);
  if (!result)
    obliterate_card(player, card);
  return result;
}

static int prevent_all_damage_of_a_source_until_eot(int player, int card, int t_player, int t_card)
{
  int legacy = in_play(t_player, t_card)
      ? create_targetted_legacy_effect(player, card, prevent_all_damage_of_a_source_until_eot_legacy,
                                        t_player, t_card)
      : create_legacy_effect(player, card, prevent_all_damage_of_a_source_until_eot_legacy);
  if (legacy != -1)
  {
    card_instance_t *instance = get_card_instance(player, legacy);
    instance->targets[0].player = t_player;
    instance->targets[0].card = t_card;
    if (instance->damage_target_player == -1)
      create_card_name_legacy(player, legacy, get_id(t_player, t_card));
  }
  return legacy;
}

static int put_into_play_a_card_from_deck_tapped_and_attacking(int player, int t_player, int deck_position)
{
  const int *deck = deck_ptr[t_player];
  if (is_what(-1, deck[deck_position], TYPE_CREATURE) &&
      grafdiggers_cages(player, TYPE_CREATURE, TUTOR_FROM_DECK))
    return -1;
  int card = add_card_to_hand(player, deck[deck_position]);
  remove_card_from_deck(t_player, deck_position);
  add_state(player, card, 0x14);
  set_special_flags(player, card, 0x50000);
  put_into_play(player, card);
  return card;
}

static int sac_at_beginning_of_next_end_step(int player, int card, int t_player, int t_card)
{
  int legacy = create_targetted_legacy_effect(player, card, sacrifice_eot, t_player, t_card);
  get_card_instance(player, legacy)->number_of_targets = 0;
  if (current_phase == 0x1f && legacy >= 0)
    get_card_instance(player, legacy)->targets[1].player = 1;
  return legacy;
}

static int select_a_card_from_deck_automatic(int player, int targ_player, int test_type,
                                              test_definition_t *this_test)
{
  if (get_tutoring_denial(player))
    return -1;
  int pos = 0;
  if (check_battlefield_for_id(1 - targ_player, CARD_ID_AVEN_MINDCENSOR) && count_deck(targ_player) > 3)
    pos = count_deck(targ_player) - 4;
  for (; pos < count_deck(player); ++pos)
    if (new_make_test(targ_player, deck_ptr[targ_player][pos], test_type, this_test))
      return pos;
  return -1;
}

static void special_null_casting_cost(int player, int card)
{
  card_ptr_t *cp = cards_ptr[get_id(player, card)];
  int cost = get_updated_casting_cost(player, card, -1, EVENT_MODIFY_COST, -1);
  COST_COLORLESS -= cost;
  int extra = get_id(player, card) == CARD_ID_HAGRA_MAULING && count_basic_lands(1 - player, -1) == 0;
  COST_COLORLESS -= extra;
  COST_BLACK -= cp->req_black;
  COST_BLUE -= cp->req_blue;
  COST_GREEN -= cp->req_green;
  COST_RED -= cp->req_red;
  COST_WHITE -= cp->req_white;
}

